import csv
import io

_DECIMAL_DIGITS = set('0123456789')


def _parse_row(row):
    fields = [row.get(field) for field in ('sku', 'name', 'qty')]
    if any(value is None for value in fields):
        raise ValueError('malformed csv row: %r' % (row,))
    sku, name, qty = (value.strip() for value in fields)
    if not sku:
        raise ValueError('empty sku: %r' % (row,))
    if not name:
        raise ValueError('empty name: %r' % (row,))
    if not qty or any(char not in _DECIMAL_DIGITS for char in qty):
        raise ValueError('invalid quantity: %r' % (row,))
    return {'sku': sku, 'name': name, 'qty': int(qty)}


def import_text(text, store, dry_run=False):
    rows = list(csv.DictReader(io.StringIO(text)))
    items = [_parse_row(row) for row in rows]
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in items:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append(
            {'sku': item['sku'], 'before': before, 'after': item})
        if not dry_run:
            store.put(item)
    return result

